mapper.select:
select uc.*, s.name as shop_name
from user_coupon uc
left join shop s on s.id = uc.shop_id
where uc.user_id = #{userId}
and uc.status = #{status}
order by uc.expire_time asc, uc.id desc

mapper.update:
update user_coupon
set status = 2, use_time = now(), order_id = #{orderId}
where id = #{id} and user_id = #{userId} and status = 1
